// lib
#pragma warning disable // keep the mixed-key analyzer error from failing the build, so the generated output can be compared
using MessagePack;

namespace Lib
{
    // Reachable only through the mismatched member below, so its formatter is generated only if that member is still walked.
    public enum Tint
    {
        Red,
        Green,
    }

    [MessagePackObject]
    public class Shape
    {
        // First keyed member: sets searchFirst = false, isIntKey = false (string-keyed object).
        [Key("name")]
        public string Name { get; set; }

        // Second member has an int key: intKey != null, stringKey == null, !isIntKey -> DoNotMixStringAndIntKeys branch.
        // old: falls through and still does the recursive collect of Tint (generated resolver gets a Tint enum formatter).
        // new: `continue` skips the rest of the iteration, so Tint is never collected.
        [Key(1)]
        public Tint Tint { get; set; }
    }
}

// app
using System;
using System.Linq;
using Lib;
using MessagePack;

public static class Program
{
    public static void Main()
    {
        // Lists what the source generator emitted: old includes a formatter for Lib.Tint, new does not.
        var generated = typeof(Shape).Assembly.GetTypes()
            .Where(t => t.FullName.Contains("Formatter") || t.FullName.Contains("Resolver"))
            .Select(t => t.FullName)
            .OrderBy(n => n, StringComparer.Ordinal);
        foreach (var name in generated)
        {
            Console.WriteLine(name);
        }

        byte[] bytes = MessagePackSerializer.Serialize(new Shape { Name = "a", Tint = Tint.Green });
        Console.WriteLine(MessagePackSerializer.ConvertToJson(bytes));
    }
}
